(() => {
const {routes,stations,find}=window.Metro;const root=document.querySelector('#station-finder');
const read=(key)=>{try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v.filter(n=>stations.some(s=>s.name===n)):[]}catch{return []}};
let favorites=read('metro-favorite-stations'),recent=read('metro-recent-stations'),selected=null,onlySaved=false;
const routeOf=id=>routes.find(r=>r.id===id);const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badges=s=>s.stops.map(t=>`<span class="station-code" style="--route:${routeOf(t.line).color}">${t.code}</span>`).join('');
root.innerHTML=`<div class="finder-intro"><div class="eyebrow">TAIPEI · NEXT FOOD STOP</div><h1>哪一站，<span>都好找。</span></h1><p>查站名、選路線，手機一按就能找周邊美食。</p></div><div class="finder-controls"><label class="finder-search"><span>⌕</span><input id="station-query" type="search" placeholder="輸入站名或代碼，例如松山、R03" aria-label="搜尋捷運站名或代碼" autocomplete="off"><button id="clear-station-query" aria-label="清除站名搜尋">×</button></label><div class="finder-row"><label for="route-select" class="sr-only">選擇捷運路線</label><select id="route-select"><option value="">全部路線（${routes.length} 條）</option>${routes.map(r=>`<option value="${r.id}">${r.id} ${r.name}</option>`).join('')}</select><button id="station-favorites" aria-pressed="false">♡ 收藏車站</button></div><div id="recent-stations" class="recent-stations"></div></div><div class="finder-grid"><div><div class="finder-results"><span id="station-count" role="status"></span><button id="finder-reset">重設篩選</button></div><div id="station-list" class="station-list"></div></div><section id="station-panel" class="station-panel" aria-label="車站美食查詢" tabindex="-1"></section></div><details class="network-sources"><summary>收錄範圍與資料來源 · ${stations.length} 個站名</summary><p>台北捷運全線及新北投、小碧潭支線；新北環狀線、三鶯線、淡海與安坑輕軌；另含桃園機場捷運已營運站。轉乘站以站名合併，顯示各線代碼。車站名單查核於 ${window.Metro.checked}，非即時營運資訊。</p><p><a href="https://www.metro.taipei/cp.aspx?n=73B51F32ED23C5E1" target="_blank" rel="noopener">台北捷運 ↗</a> · <a href="https://www.ntmetro.com.tw/" target="_blank" rel="noopener">新北捷運 ↗</a> · <a href="https://www.tymetro.com.tw/tymetro-new/tw/_pages/travel-guide/road.php" target="_blank" rel="noopener">桃園捷運 ↗</a></p><p>全站皆提供外部地圖美食搜尋；只有「已整理店家」提供本站已查核的餐廳資訊，未串接即時餐廳資料庫。</p></details>`;
const q=root.querySelector('#station-query'),line=root.querySelector('#route-select'),panel=root.querySelector('#station-panel');
function persist(key,v){try{localStorage.setItem(key,JSON.stringify(v));}catch{toast('此裝置無法儲存，本次操作仍可使用');}}
function recents(){root.querySelector('#recent-stations').innerHTML=recent.length?'<span>最近查詢</span>'+recent.slice(0,4).map(n=>`<button data-station="${esc(n)}">${esc(n)}</button>`).join(''):'';}
function render(){const items=find({query:q.value,line:line.value,saved:onlySaved?favorites:null});root.querySelector('#station-count').textContent=`${onlySaved?'收藏車站':'可查詢車站'} · ${items.length} 站`;root.querySelector('#station-list').innerHTML=items.length?items.map(s=>`<button class="station-tile ${selected?.name===s.name?'selected':''}" data-station="${esc(s.name)}" aria-pressed="${selected?.name===s.name}"><span class="station-tile-top">${badges(s)}</span><strong>${esc(s.name)}${favorites.includes(s.name)?' ♥':''}</strong><small>${s.stops.map(t=>t.branch||routeOf(t.line).name).join(' · ')} <span>→</span></small></button>`).join(''):'<div class="station-no-results">'+(onlySaved?'還沒有符合條件的收藏車站。':'找不到符合條件的車站。')+'<br>試試其他站名，或重設路線篩選。</div>';root.querySelector('#station-favorites').setAttribute('aria-pressed',onlySaved);recents();}
const real={
 '松山':[{name:'路易莎・松山蔦屋門市',desc:'CITYLINK 松山壹號店 3F；松山路11號。',url:'https://www.citylink.tw/songshan/?p=7755'}],
 '台北101/世貿':[{name:'鼎泰豐・101 店',desc:'台北101 B1；市府路45號。',url:'https://www.dintaifung.com.tw/store.php'}],
 '市政府':[{name:'欣葉台菜・信義 A9 店',desc:'新光三越 A9 館 8F；松壽路9號。',url:'https://www.shinyeh.com.tw/content/zh/brand/Store.aspx?BrandId=1&Id=5'}]
};
function showStation(name,scroll=true){selected=stations.find(s=>s.name===name);if(!selected)return;recent=[name,...recent.filter(n=>n!==name)].slice(0,6);persist('metro-recent-stations',recent);panel.innerHTML=`<div class="panel-top"><span class="eyebrow">YOUR NEXT STOP</span><button id="favorite-current" aria-label="收藏${esc(name)}站" aria-pressed="${favorites.includes(name)}">${favorites.includes(name)?'♥ 已收藏':'♡ 收藏此站'}</button></div><div>${badges(selected)}</div><h2>${esc(name)}</h2><p class="station-line-names">${selected.stops.map(t=>routeOf(t.line).name+(t.branch?' · '+t.branch:'')).join(' / ')}</p><label for="meal-select">這一站，想吃什麼？</label><select id="meal-select"><option value="美食">全部美食</option><option value="早餐">早餐</option><option value="午餐">午餐</option><option value="晚餐">晚餐</option><option value="咖啡甜點">咖啡甜點</option><option value="素食">素食</option></select><label for="dish-query">料理關鍵字（選填）</label><input id="dish-query" type="search" placeholder="例如：牛肉麵、小籠包" maxlength="60"><a id="nearby-food" class="nearby-button" target="_blank" rel="noopener noreferrer">開啟周邊美食地圖 ↗</a><p class="external-note">將開啟 Google Maps 搜尋結果，評價、價位與營業狀態以地圖及店家資訊為準。</p><div class="curated-stations"><h3>已整理店家</h3>${real[name]?real[name].map(r=>`<article><strong>${r.name}</strong><p>${r.desc}</p><a href="${r.url}" target="_blank" rel="noopener noreferrer">官方資訊 ↗</a></article>`).join(''):'<p>本站尚未整理此站的店家，仍可透過上方地圖查詢周邊美食。</p>'}</div><a class="station-official" href="${routeOf(selected.stops[0].line).source}" target="_blank" rel="noopener noreferrer">營運單位車站資訊 ↗</a>`;
const updateMap=()=>{const qualifier=selected.stops.some(t=>t.line==='A')?'桃園機場捷運':selected.stops.some(t=>['V','K','Y','LB'].includes(t.line))?'新北捷運':'台北捷運';const query=`${qualifier} ${selected.name}站 附近 ${panel.querySelector('#meal-select').value} ${panel.querySelector('#dish-query').value.trim()}`;panel.querySelector('#nearby-food').href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(query);};panel.querySelector('#meal-select').onchange=updateMap;panel.querySelector('#dish-query').oninput=updateMap;panel.querySelector('#favorite-current').onclick=()=>{favorites=favorites.includes(name)?favorites.filter(n=>n!==name):[...favorites,name];persist('metro-favorite-stations',favorites);showStation(name,false);};updateMap();render();if(scroll&&matchMedia('(max-width: 760px)').matches){panel.scrollIntoView({behavior:'smooth',block:'start'});panel.focus({preventScroll:true});}}
root.addEventListener('click',e=>{const tile=e.target.closest('[data-station]');if(tile)showStation(tile.dataset.station)});q.oninput=render;line.onchange=render;root.querySelector('#clear-station-query').onclick=()=>{q.value='';render();q.focus()};root.querySelector('#station-favorites').onclick=()=>{onlySaved=!onlySaved;render()};root.querySelector('#finder-reset').onclick=()=>{q.value='';line.value='';onlySaved=false;render()};
document.querySelectorAll('[href="#station-finder"]').forEach(a=>a.addEventListener('click',()=>{setTimeout(()=>q.focus({preventScroll:true}),250)}));showStation('松山',false);render();
})();
